/* @autogenerated */
package net.civeira.phylax.bootstrap.install;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.nio.file.Path;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.mockito.ArgumentCaptor;

import net.civeira.phylax.common.infrastructure.config.IsolatedConfigLoaderTestSupport;
import net.civeira.phylax.common.security.SecureTokenService;
import net.civeira.phylax.features.access.apikeyclient.domain.ApiKeyClient;
import net.civeira.phylax.features.access.apikeyclient.domain.gateway.ApiKeyClientCommandRepositoryGateway;
import net.civeira.phylax.features.access.relyingparty.domain.RelyingParty;
import net.civeira.phylax.features.access.relyingparty.domain.gateway.RelyingPartyCommandRepositoryGateway;
import net.civeira.phylax.features.access.role.domain.Role;
import net.civeira.phylax.features.access.role.domain.gateway.RoleCommandRepositoryGateway;
import net.civeira.phylax.features.access.tenant.domain.Tenant;
import net.civeira.phylax.features.access.tenant.domain.gateway.TenantCommandRepositoryGateway;
import net.civeira.phylax.features.access.trustedclient.domain.TrustedClient;
import net.civeira.phylax.features.access.trustedclient.domain.gateway.TrustedClientCommandRepositoryGateway;
import net.civeira.phylax.features.access.user.domain.User;
import net.civeira.phylax.features.access.user.domain.gateway.UserCommandRepositoryGateway;
import net.civeira.phylax.features.access.usergroupmembership.domain.UserGroupMembership;
import net.civeira.phylax.features.access.usergroupmembership.domain.gateway.UserGroupMembershipCommandRepositoryGateway;
import net.civeira.phylax.features.access.userroleassignment.domain.UserRoleAssignment;
import net.civeira.phylax.features.access.userroleassignment.domain.gateway.UserRoleAssignmentCommandRepositoryGateway;

class InstallAccessUnitTest {
  private UserCommandRepositoryGateway users;
  private RelyingPartyCommandRepositoryGateway parties;
  private TrustedClientCommandRepositoryGateway clients;
  private ApiKeyClientCommandRepositoryGateway apiKeys;

  @TempDir
  Path external;

  @BeforeEach
  void setUp() {
    users = mock(UserCommandRepositoryGateway.class);
    parties = mock(RelyingPartyCommandRepositoryGateway.class);
    clients = mock(TrustedClientCommandRepositoryGateway.class);
    apiKeys = mock(ApiKeyClientCommandRepositoryGateway.class);
    when(users.create(any(User.class))).thenAnswer(inv -> inv.getArgument(0));
    when(parties.create(any(RelyingParty.class))).thenAnswer(inv -> inv.getArgument(0));
    when(clients.create(any(TrustedClient.class))).thenAnswer(inv -> inv.getArgument(0));
  }

  @Test
  void testGenerateTheMissingSecretsWithATemporalRootPassword() {
    seed(List.of("prod"), Map.of()).run();

    User root = created(users, User.class);
    assertEquals("ROOT", root.getName());
    assertTrue(root.isTemporalPassword());
    List<ApiKeyClient> keys = createdKeys();
    assertTrue(keys.get(0).getKey().orElseThrow().startsWith("hcaik_"),
        keys.get(0).getKey().orElseThrow());
    assertTrue(keys.get(1).getKey().orElseThrow().startsWith("sck_"),
        keys.get(1).getKey().orElseThrow());
    assertTrue(keys.get(0).getKey().orElseThrow().length() > "hcaik_".length() + 30);
  }

  @Test
  void testUseTheDevValues() {
    seed(List.of("dev"), Map.of()).run();

    User root = created(users, User.class);
    assertEquals(Boolean.FALSE, root.isTemporalPassword());
    assertEquals("civi-acme-api", created(parties, RelyingParty.class).getCode());
    assertEquals("civi-acme-ui", created(clients, TrustedClient.class).getCode());
    assertTrue(createdKeys().get(0).getKey().orElseThrow().startsWith("hcaik_01jtteh"));
  }

  @Test
  void testUseTheSecretsFromTheEnvironment() {
    seed(List.of("prod"), Map.of("OIDC_API_KEYS_COLLECTOR", "hcaik_from_env")).run();

    assertEquals("hcaik_from_env", createdKeys().get(0).getKey().orElseThrow());
  }

  @Test
  void testSkipWhenThereAreUsers() {
    when(users.countForUpdate(any())).thenReturn(1L);

    seed(List.of("prod"), Map.of()).run();

    verify(users, never()).create(any(User.class));
  }

  private InstallAccess seed(List<String> profiles, Map<String, String> environment) {
    RoleCommandRepositoryGateway roles = mock(RoleCommandRepositoryGateway.class);
    when(roles.create(any(Role.class))).thenAnswer(inv -> inv.getArgument(0));
    TenantCommandRepositoryGateway tenants = mock(TenantCommandRepositoryGateway.class);
    when(tenants.create(any(Tenant.class))).thenAnswer(inv -> inv.getArgument(0));
    UserRoleAssignmentCommandRepositoryGateway assignments =
        mock(UserRoleAssignmentCommandRepositoryGateway.class);
    when(assignments.create(any(UserRoleAssignment.class))).thenAnswer(inv -> inv.getArgument(0));
    UserGroupMembershipCommandRepositoryGateway memberships =
        mock(UserGroupMembershipCommandRepositoryGateway.class);
    when(memberships.create(any(UserGroupMembership.class))).thenAnswer(inv -> inv.getArgument(0));
    when(apiKeys.create(any(ApiKeyClient.class))).thenAnswer(inv -> inv.getArgument(0));
    return new InstallAccess(users, roles, tenants, clients, parties, assignments, memberships,
        apiKeys, IsolatedConfigLoaderTestSupport.loader(external, profiles, environment),
        new SecureTokenService());
  }

  private List<ApiKeyClient> createdKeys() {
    ArgumentCaptor<ApiKeyClient> captor = ArgumentCaptor.forClass(ApiKeyClient.class);
    verify(apiKeys, org.mockito.Mockito.times(2)).create(captor.capture());
    return captor.getAllValues();
  }

  private static <T> T created(Object gateway, Class<T> type) {
    ArgumentCaptor<T> captor = ArgumentCaptor.forClass(type);
    if (gateway instanceof UserCommandRepositoryGateway g) {
      verify(g).create((User) captor.capture());
    } else if (gateway instanceof RelyingPartyCommandRepositoryGateway g) {
      verify(g).create((RelyingParty) captor.capture());
    } else if (gateway instanceof TrustedClientCommandRepositoryGateway g) {
      verify(g).create((TrustedClient) captor.capture());
    }
    return captor.getValue();
  }
}
